#define WIN32_ARITY_N ((int)(sizeof g_win32_arity / sizeof *g_win32_arity))

/* -1 when the name is unknown, so the caller can say so out loud */
static int win32_arity_of(const char *sym)
{
    int lo = 0, hi = WIN32_ARITY_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2, c = strcmp(g_win32_arity[mid].sym, sym);
        if (c == 0) return g_win32_arity[mid].bytes;
        if (c < 0) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}

